{
  "claims": [
    {
      "claim": "Cephradine, a close cephem analog in which the query's p-hydroxyphenyl side chain is replaced by a cyclohexadienyl group, shows near-complete absolute oral bioavailability in humans (94% in young/elderly, 85% in non-pregnant women, and ~90-100% overall), directly supporting F >= 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 1"],
      "record_ids": ["Record 1-1", "Record 1-2", "Record 1-3", "Record 1-4", "Record 1-5"]
    },
    {
      "claim": "Amoxicillin, which shares the exact 4-hydroxyphenylglycyl side chain and a closely related beta-lactam scaffold, has absolute oral bioavailability values of 70-93% in healthy/normal human subjects and generally ~55-59% even in frail/elderly/paediatric settings, all above the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 3", "Molecule 4"],
      "record_ids": ["Record 3-1", "Record 3-2", "Record 3-3", "Record 4-1", "Record 4-2", "Record 4-3", "Record 4-4", "Record 4-5", "Record 4-6", "Record 4-7", "Record 4-8", "Record 4-9", "Record 4-10"]
    },
    {
      "claim": "Additional oral cephalosporins with similar cephem cores (cefroxadine, cephradine, and an SP cephalosporin) show complete or substantial human oral bioavailability (100%, complete, and ~40%), confirming that this scaffold is well absorbed orally.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 5", "Molecule 6", "Molecule 8"],
      "record_ids": ["Record 5-1", "Record 6-1", "Record 8-1"]
    },
    {
      "claim": "Cephalexin, the direct des-hydroxy analog of the query, is a well-documented PEPT1 substrate with high/complete human intestinal absorption; its low passive-permeability values in artificial/Caco-2 systems are false negatives for such substrates and do not indicate low F. Horse and inhibitor/disease-modified low-bioavailability values are not representative of normal human oral absorption.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 11", "Molecule 13"],
      "record_ids": ["Record 11-15", "Record 11-17", "Record 11-18", "Record 11-19", "Record 11-21", "Record 11-24", "Record 11-27", "Record 11-28", "Record 11-29", "Record 11-32", "Record 11-36", "Record 11-46", "Record 13-1"]
    },
    {
      "claim": "Ampicillin, a structurally related aminopenicillin with the same 2-amino-2-phenylacetamido side-chain type, reaches human oral bioavailability of roughly 29-62%; although lower than the cephems, all reported mean values remain above 20%, supporting a pass rather than a fail.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 9", "Molecule 10"],
      "record_ids": ["Record 9-1", "Record 10-1", "Record 10-2", "Record 10-3", "Record 10-4", "Record 10-5", "Record 10-6", "Record 10-7", "Record 10-8", "Record 10-9", "Record 10-10"]
    },
    {
      "claim": "The fed-state-specific cefprozil AUC record shows substantial oral drug exposure under fed conditions but no IV comparator; it cannot quantify F, yet it provides no evidence that F falls below 20% in the fed state.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 12"],
      "record_ids": ["Record 12-1"]
    },
    {
      "claim": "Low-bioavailability records from cefazolin (parenteral cephalosporin), oral ceftriaxone, horse cephalexin, and cephalexin with inhibitors/disease are poorly transferable to the query's human oral condition and do not outweigh the strong positive human evidence; cefoperazone hepatic-clearance data do not measure oral F.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 2", "Molecule 7", "Molecule 11", "Molecule 14"],
      "record_ids": ["Record 2-1", "Record 7-1", "Record 11-2", "Record 11-3", "Record 11-4", "Record 11-5", "Record 11-7", "Record 11-9", "Record 14-1"]
    }
  ],
  "final_prediction": "pass"
}
